<?php
namespace App\Http\Controllers; use App\Models\{Withdrawal,WithdrawalStatusHistory,AccountLedger,AppNotification}; use App\Http\Requests\StoreWithdrawalRequest; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class WithdrawalController extends Controller {public function index(Request $r){$u=auth()->user();$q=Withdrawal::with('customer')->when($u->role==='nasabah',fn($x)=>$x->where('customer_id',$u->id))->when($r->status,fn($x,$s)=>$x->where('status',$s));$withdrawals=$q->latest()->paginate(10)->withQueryString();return view('withdrawals.index',compact('withdrawals'));} public function create(){return view('withdrawals.create',['balance'=>auth()->user()->balance()]);} public function store(StoreWithdrawalRequest $r){$v=$r->validated();$u=auth()->user();abort_if((float)$v['amount']>$u->balance(),422,'Saldo tidak mencukupi.');$w=DB::transaction(function()use($v,$u){$w=Withdrawal::create(['code'=>'TRK-'.now()->format('YmdHis').'-'.random_int(10,99),'customer_id'=>$u->id,'amount'=>$v['amount'],'status'=>'pending','notes'=>$v['notes']??null]);WithdrawalStatusHistory::create(['withdrawal_id'=>$w->id,'from_status'=>null,'to_status'=>'pending','changed_by'=>$u->id,'notes'=>'Permintaan penarikan dibuat']);return $w;});return redirect()->route('withdrawals.show',$w)->with('success','Permintaan penarikan berhasil dibuat.');} public function show(Withdrawal $withdrawal){$this->owner($withdrawal);$withdrawal->load(['customer','processor','histories.changer']);return view('withdrawals.show',compact('withdrawal'));} public function updateStatus(Request $r,Withdrawal $withdrawal){abort_unless(in_array(auth()->user()->role,['admin','petugas'],true),403);$data=$r->validate(['status'=>['required','in:approved,paid,rejected'],'notes'=>['nullable','string','max:500'],'payment_proof'=>['nullable','image','mimes:jpg,jpeg,png','max:2048']]);$allowed=['pending'=>['approved','rejected'],'approved'=>['paid','rejected'],'paid'=>[],'rejected'=>[]];abort_unless(in_array($data['status'],$allowed[$withdrawal->status]??[],true),422,'Perubahan status tidak sesuai urutan.');if($data['status']==='paid')abort_if((float)$withdrawal->amount>$withdrawal->customer->balance(),422,'Saldo nasabah saat ini tidak mencukupi.');DB::transaction(function()use($r,$withdrawal,$data){$old=$withdrawal->status;$upd=['status'=>$data['status'],'processed_by'=>auth()->id()];if($r->hasFile('payment_proof'))$upd['payment_proof']=$r->file('payment_proof')->store('withdrawals','public');$withdrawal->update($upd);WithdrawalStatusHistory::create(['withdrawal_id'=>$withdrawal->id,'from_status'=>$old,'to_status'=>$data['status'],'changed_by'=>auth()->id(),'notes'=>$data['notes']??null]);if($data['status']==='paid')AccountLedger::firstOrCreate(['reference_type'=>'withdrawal','reference_id'=>$withdrawal->id],['customer_id'=>$withdrawal->customer_id,'type'=>'debit','amount'=>-(float)$withdrawal->amount,'description'=>'Penarikan '.$withdrawal->code]);AppNotification::create(['user_id'=>$withdrawal->customer_id,'title'=>'Status penarikan berubah','message'=>"{$withdrawal->code}: {$old} → {$data['status']}",'link'=>route('withdrawals.show',$withdrawal)]);});return back()->with('success','Status penarikan berhasil diperbarui.');} private function owner(Withdrawal $w):void{if(auth()->user()->role==='nasabah'&&$w->customer_id!==auth()->id())abort(403,'Bukan data Anda.');}}
